                continue
            candidates = {}
            for rad in range(1, max(h, w)):
                for rr in range(max(0, r-rad), min(h, r+rad+1)):
                    for cc in range(max(0, c-rad), min(w, c+rad+1)):
                        if max(abs(rr-r), abs(cc-c)) != rad:
                            continue
                        color = grid[rr][cc]
                        if color in noise:
                            continue
                        candidates[color] = candidates.get(color, 0) + 1
                if candidates:
                    break
            if candidates:
                out[r][c] = max(candidates, key=candidates.get)
