def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()

    # Keep substantial rectangular objects, repairing intrusions/holes;
    # clear isolated noise and stray marks to the background.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            if len(cells) < 4:
                continue
            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)
            area = (r1-r0+1) * (c1-c0+1)
            if area <= len(cells) * 2:
                for y in range(r0, r1+1):
                    for x in range(c0, c1+1):
                        out[y][x] = color

    # Remove non-background singleton/interruption colors.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or out[r][c] != grid[r][c]:
                continue
            same = sum(0 <= r+dr < h and 0 <= c+dc < w and grid[r+dr][c+dc] == grid[r][c]
                       for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)))
            if same == 0:
                out[r][c] = bg
    return out
